   assert t in allowed,(n,t)
   assert not attrs.strip(),(n,attrs)
  if result['change_type']=='full_repeal':
   assert plain(x).startswith(('Le présent article est abrogé','Abrogé')),n
   assert len(result['repeal_scope'])>=30 and result['repeal_policy_id']=='editorial_direction_2026_10_19',n
  elif result['change_type']=='normative_reduction':
   assert result['reform_policy_id']=='editorial_direction_2026_10_19'
   assert all(len(p)>=30 for p in result['removed_provisions']),n
 if source.get('benefit_check_required'): assert len(result.get('benefit_review',''))>=100,n
 required=r['requirements'][source['code_id']+'|'+source['source_id']]
 assert [c['target_key'] for c in result['reference_checks']]==required,n
 for check in result['reference_checks']:
  assert check['view_sha256']==r['targets'][check['target_key']]['view_sha256'] and len(check['assessment'])>=80,n
 for e in im['effects']:
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96,n
  for q,key in [('source_quote','source_xml'),('proposed_quote','proposed_xml')]:
   assert len(e[q])>=12 and e[q] in plain((source if key=='source_xml' else result)[key]),(n,q,e[q])
 print(n,result['status'],im['classification'],'effects',len(im['effects']),'refs',len(required))
print('Tous les contrôles structurels et citations exactes passent. Ils ne constituent pas une validation juridique.')
